-- Biology 1 final module. Run seed_biology1_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'biology-1';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Stewardship Science Investigation$j$, $j${"prompt": "Plan and report a science investigation about a living system near your home, school or church, such as a garden, a pond, a tree, a yard or a schoolyard. Show your work, label each part and write complete sentences. Psalm 111:2 says, The works of the LORD are great, sought out of all them that have pleasure therein. Seek out the works of the Lord with care and joy.\n\nPart 1: Question and Hypothesis. State a testable question about the living system and a hypothesis with a reason. Name the independent variable, the dependent variable, at least three controlled variables and a control group.\n\nPart 2: Procedure and Data. Write a numbered procedure that another student could repeat. Include a data table with at least three trials or three sample sites and a safe way to collect data. Invent realistic sample data if you cannot collect it, and say that it is sample data. Find an average for each group and make a labeled graph.\n\nPart 3: Cells and Chemistry. Choose one organism in your system. Name its cell type, three organelles that matter to its life, and one biomolecule it uses. Tell how water helps it survive.\n\nPart 4: Energy and Matter. Show how energy and one cycled element (carbon or nitrogen) move through your system. Write the photosynthesis and cellular respiration equations in words and tell where each occurs.\n\nPart 5: Heredity and Change. Give one trait of an organism in your system and show a Punnett square for a cross that could produce it. Explain how variation and natural selection could change the population over many generations.\n\nPart 6: Ecology and Stewardship. Draw or describe a food web with at least six organisms. Tell what the carrying capacity depends on and one way people help or harm the system. Write three actions for stewardship, using Genesis 2:15, which says, And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it.\n\nPart 7: Reflection. In at least 100 words, explain what this course taught you about the wisdom of God in creation, the value of honest evidence, and your responsibility to care for living things.", "rubric": "200 points. Part 1, question and hypothesis: 24 points. Part 2, procedure, data and graph: 36 points. Part 3, cells and chemistry: 28 points. Part 4, energy and matter: 30 points. Part 5, heredity and change: 28 points. Part 6, ecology and stewardship: 32 points. Part 7, reflection: 14 points. Clear organization and complete sentences: 8 points. A score of 140 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Stewardship Science Investigation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Biology 1$j$, $j${"questions": [{"q": "A testable explanation or prediction in science is called a:", "options": ["Theory", "Variable", "Hypothesis", "Conclusion"]}, {"q": "In an experiment on fertilizer and plant height, the plant height is the:", "options": ["Control group", "Independent variable", "Constant", "Dependent variable"]}, {"q": "The special properties of water, such as cohesion and a high specific heat, result from:", "options": ["Chlorophyll", "Mutations", "Hydrogen bonds", "Peptide bonds"]}, {"q": "The monomers of proteins are:", "options": ["Simple sugars", "Fatty acids", "Amino acids", "Nucleotides"]}, {"q": "Which organelle is the site of most ATP production in a cell?", "options": ["Lysosome", "Ribosome", "Golgi apparatus", "Mitochondrion"]}, {"q": "A red blood cell placed in pure water is in a hypotonic solution and will:", "options": ["Divide", "Stay the same", "Lose water and shrivel", "Take in water and swell"]}, {"q": "The stage of mitosis in which chromosomes line up in the middle of the cell is:", "options": ["Telophase", "Prophase", "Anaphase", "Metaphase"]}, {"q": "The overall reaction of photosynthesis uses carbon dioxide, water and light to make:", "options": ["Proteins and DNA", "Glucose and oxygen", "ATP and water only", "Lactic acid"]}, {"q": "Which process produces the most ATP from a molecule of glucose?", "options": ["Aerobic respiration", "Glycolysis alone", "Fermentation", "Photosynthesis"]}, {"q": "If the DNA template reads TACGGA, the mRNA will read:", "options": ["AUGCCU", "UACGGA", "AUGGGA", "ATGCCT"]}, {"q": "Two heterozygous parents (Aa times Aa) have a child. The chance that the child is aa is:", "options": ["50 percent", "75 percent", "25 percent", "100 percent"]}, {"q": "Which is a source of genetic variation in sexual reproduction?", "options": ["Photosynthesis", "Osmosis", "Cytokinesis", "Crossing over"]}, {"q": "Natural selection results in a population in which:", "options": ["All traits stay the same forever", "Helpful inherited traits become more common", "Mutations stop", "Individuals change by wanting to"]}, {"q": "In the scientific name Homo sapiens, sapiens is the:", "options": ["Family", "Species", "Domain", "Genus"]}, {"q": "In a food chain, about how much of the energy at one trophic level reaches the next?", "options": ["90 percent", "100 percent", "50 percent", "10 percent"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Biology 1$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,2,3,3,3,1,0,0,2,3,1,1,3}'::int[], array[$j$A hypothesis is a testable explanation or prediction that evidence can support or reject.$j$,$j$The dependent variable is measured as the response.$j$,$j$Polar water molecules form hydrogen bonds that cause these properties.$j$,$j$Proteins are chains of amino acids.$j$,$j$Mitochondria carry out most of cellular respiration.$j$,$j$There is less solute outside, so water moves into the cell.$j$,$j$Chromosomes align in the middle during metaphase.$j$,$j$Photosynthesis produces glucose and releases oxygen.$j$,$j$Aerobic respiration yields about 36 to 38 ATP.$j$,$j$mRNA is complementary to the template and uses uracil instead of thymine.$j$,$j$The Punnett square gives 1 AA, 2 Aa and 1 aa.$j$,$j$Crossing over shuffles alleles between homologous chromosomes.$j$,$j$Individuals with helpful traits survive and leave more offspring.$j$,$j$The second word of a binomial name is the species.$j$,$j$About 10 percent is passed on and the rest is used or lost as heat.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Biology 1$j$ on conflict (item_id) do nothing;
end
$seed$;
